using BanhangcodeX.Models;using Microsoft.EntityFrameworkCore;
namespace BanhangcodeX.Data;
public class AppDbContext(DbContextOptions<AppDbContext> o):DbContext(o){public DbSet<Customer> Customers=>Set<Customer>();public DbSet<Product> Products=>Set<Product>();public DbSet<Order> Orders=>Set<Order>();public DbSet<OrderDetail> OrderDetails=>Set<OrderDetail>();public DbSet<AppUser> Users=>Set<AppUser>();protected override void OnModelCreating(ModelBuilder b){b.Entity<AppUser>().HasIndex(x=>x.UserName).IsUnique();b.Entity<Customer>().HasIndex(x=>x.Code).IsUnique();b.Entity<Product>().HasIndex(x=>x.Code).IsUnique();b.Entity<Order>().HasIndex(x=>x.OrderCode).IsUnique();b.Entity<Order>().HasOne(x=>x.Customer).WithMany(x=>x.Orders).HasForeignKey(x=>x.CustomerId).OnDelete(DeleteBehavior.Restrict);b.Entity<OrderDetail>().HasOne(x=>x.Order).WithMany(x=>x.Details).HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.Cascade);foreach(var t in new[]{typeof(Customer),typeof(Product),typeof(Order),typeof(OrderDetail)})foreach(var p in t.GetProperties().Where(x=>x.PropertyType==typeof(decimal)))b.Entity(t).Property(p.Name).HasPrecision(18,2);b.Entity<OrderDetail>().Property(x=>x.WeightKg).HasPrecision(10,3);}}

